"""MLD_NOTE 생성 (build_malouda.py가 부름)"""
import re, sys

def d_(s):
    y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"
def c3(v): return "·".join(map(str, v))

def make(g):
    E, M, ST, ORDER = g["E"], g["M"], g["ST"], g["ORDER"]
    NG, NGo, NA, MIN_TOT = g["NG"], g["NGo"], g["NA"], g["MIN_TOT"]
    GAP = g["GAP"]
    first, last = M[0], M[-1]
    pre = sum(1 for r in E if r[0] == "a" and r[9] < GAP)
    ties = [r for r in E if len(r) > 14]
    ntie, ntieg = len(ties), len({(r[9], r[1]) for r in ties})
    pk = sum(1 for r in E if r[7 - 0 + 1] == 1 and r[0] == "g")
    L = [
        f"플로랑 말루다(샤토루·갱강·리옹·첼시·트라브존스포르·메스·델리 다이너모스·와디 데글라·디페르당주 03)의 클럽 공식 경기 {NG}경기({d_(first[0])} 로리앙전 ~ {d_(last[0])} 위스테르트전)에서 나온 {NGo}골 {NA}도움, 친선경기 제외",
        "클럽별 경기·골·도움: " + ", ".join(f"{n} {c3(ST[n])}" for n in ORDER),
        f"경기·출전 분·골 시간·골 뒤 스코어는 Transfermarkt 선수 경기 성적(API, 출전 {NG}경기·{MIN_TOT}분)과 경기 리포트 기준이며 출전 시간 90분 추정 경기는 없음(출전 분은 다른 출처로 대조하지 못함). 경기 수·골은 영어 위키백과의 시즌별 클럽 기록과 같음(갱강 2002-03만 영어 위키백과 40경기, Transfermarkt·프랑스어 위키백과 41경기라 41경기를 씀)",
        "유스·2군 경기는 없고, 프랑스 대표팀·프랑스령 기아나 대표팀·U-18 대표팀 경기와 친선경기는 뺌",
        "골 시각·골 직전 스코어는 Transfermarkt 기준이며 FotMob(2010-11 이후 74개 골·도움 기록)과 스코어가 모두 같고 분은 2분 이내(FotMob은 추가시간 골을 90분으로 적은 경우가 있어 Transfermarkt의 90+2 같은 표기를 씀)",
        "PK 골은 3개(2013.12.8 가지안테프스포르전 57분, 2013.12.29 안탈리아스포르전 44분, 2014.11.1 캉전 90분). 본인이 얻은 PK를 자기 도움으로 적은 2013.12.29 기록은 도움에 넣지 않음",
        "2013.12.1 트라브존스포르 3-1 카이세리 에르지예스스포르전 57분 골은 FotMob이 상대 선수 자책골로 적었으나 Transfermarkt와 Timeturk 경기 기사·경기 기록 사이트가 모두 말루다 골로 적어 골로 셈. 경기 날짜는 12월 1일(영어 위키백과의 '11월 1일'은 오기로 봄)",
        "2004.1.24 쿠프 드 프랑스 부르앙브레스 페로나전(리옹 5-0) 85분 골은 Transfermarkt 골 목록에 리옹 자책골 한 개(로페스 72분)가 빠져 있어 골 직전 스코어를 프랑스어 위키백과 시즌 문서의 골 순서(스코어 4-0)로 고침. 말루다 골 시간은 둘 다 85분",
        f"도움 {NA}개 = Transfermarkt 도움 115개 − 제외 {115 - NA}개. 제외한 것: 상대 자책골 유도 1개(2004.2.25 챔스 레알 소시에다드전 18분), PK 유도 1개(2013.11.10 겐츨레르비를리이전 콜만), 'Shot on goal' 리바운드 1개(2013.10.28 카심파샤전 파울루 엔히키 24분), 2014.8 이후 두 번째 출처로 확인하지 못한 와디 데글라 8개·디페르당주 3개",
        "2013.9.29 코니아스포르전 71분 유믈루 골은 Transfermarkt 도움 유형이 'Shot on goal'이지만 FotMob이 말루다 도움으로 센 기록이라 도움에 넣음(FotMob이 센 리바운드성 도움은 FotMob을 따르는 기존 선례)",
        f"도움은 2014.8.1 이전({pre}개)은 Transfermarkt 단일 출처이며 다른 출처로 대조하지 못함(도움 유형 칸이 빈 도움 포함). 프랑스어 위키백과의 도움 합계(103)는 Transfermarkt(115)보다 12개 적고 특히 리옹 시기(30 대 39)가 다름. 이 계산기는 Transfermarkt를 따름",
        "2014.8 이후 도움: 메스 5개는 Transfermarkt와 FotMob 경기 이벤트가 같음. 델리 다이너모스 11개(2015 시즌 8개·2016 시즌 3개)는 FotMob 경기 이벤트에 도움이 없으나 FotMob 선수 경력의 시즌 도움 수(8·3)가 Transfermarkt와 같고 인도 슈퍼리그 공식 사이트도 2015 시즌 도움 8개(리그 공동 1위, 2015.10.18 케랄라전 가제 결승골 도움 언급)라고 적어 모두 넣음. 한 경기별 확인은 못 함",
        "와디 데글라 임대 도움 8개(2016.2.14 자말렉·2.17 탈라에 엘 가이시·2.21 엔피·3.7 페트로제트·5.7 알아흘리·6.8 모카울룬·7.8 이티하드 알렉산드리아 2개)는 FotMob에 도움이 없고 이집트 매체 Youm7(2016.6.13)만 이 중 5개(자말렉·탈라에·엔피·페트로제트·모카울룬)를 말루다 도움으로 적어 두 번째 출처가 없어 모두 뺌. 디페르당주 도움 3개(2018.3.11 빅토리아 로스포르·3.25 쿠프 에르펠당주·5.4 위스테르트)도 FotMob 도움 0, 기사 확인 실패로 뺌",
        "상대 Elo는 기존 선수 자료의 같은 팀·같은 시즌 값을 먼저 쓰고, 없으면 그 시즌 최종 순위(Transfermarkt 순위표)를 기존 리그 순위값에 넣음: 프랑스 1부는 기존 18팀·20팀 순위값, 프랑스 2부(20팀)는 기존 리그2 순위값(3위 1603은 2·4위 사이 가운데, 7·8·12·13위도 앞뒤 순위값 사이 직선), 튀르키예 2013-14는 기존 순위값 사이 직선(13위 1402·14위 1386·15위 1370), 포르투갈 2009-10은 기존 순위값(FC 포르투 3위 1716)",
        "직접 추정(lv에 '추정' 표시): 인도 슈퍼리그 2015·2016(8팀)은 델 피에로 선례대로 1위 1300~꼴찌 1200 직선(순위는 Transfermarkt 순위표). 이집트 프리미어리그 2015-16(18팀)은 기존 이집트 평균 1415·흩어짐 119에 튀르키예 18팀 순위 곡선을 적용(1위 1712·9위 1396·10위 1381·16위 1288). 키프로스(아폴론 리마솔 2013-14 3위)는 기존 키프로스 상위권 1450, 알바니아(쿠케시 2013-14 2위)는 기존 알바니아 상위권 1300, 폴란드(레기아 2013-14 1위)는 기존 레기아 2011-12 1480과 같게 둠. 쿠프 드 프랑스 2003-04 상대 부르앙브레스 페로나(3부 나시오날, 순위 미확인 중위권 1303)와 엑스트라 아이르(아마추어, 드록바 자료 세이시네 파리제 1100과 같게)도 추정",
        f"국내컵(쿠프 드 프랑스·쿠프 드 라 리그·FA컵·리그컵)은 16강까지(FA컵 5라운드·리그컵 16강 포함) 낮은 비중, 8강(FA컵 6라운드·리그컵 5라운드) 이후 높은 비중, 커뮤니티 실드는 국내컵 결승으로 계산함. 챔스 조별은 리그 단계, 유로파 예선은 예선으로 계산함. 인도 슈퍼리그 플레이오프 준결승 4경기는 출전 기록에만 있고 골·도움은 없음",
        f"두 경기 합산 기록 {ntie}개({ntieg}경기)는 합산 S로 계산함. 원정 다득점은 UEFA 대회 2020-21시즌까지·잉글랜드 리그컵 준결승 2017-18시즌까지 적용하고 2차전은 연장 있음. 자신이 뛰지 않은 1차전 쿠케시전(2013.8.22 쿠케시 0-2 트라브존스포르)은 Transfermarkt 리포트의 스코어를 썼음",
        "단판 토너먼트로 연장·승부차기까지 간 경기의 기록은 연장 경기로 계산함: 2007.8.5 커뮤니티 실드 맨유전(52분 출전, 승부차기 패), 2009.12.2 리그컵 8강 블랙번전(120분, 승부차기 패), 2011.10.26 리그컵 에버턴전(120분, 연장 116분 도움), 2003.1.19 쿠프 드 라 리그 낭트전(120분, 연장 114분 골, 승부차기 패), 1999.11.24 쿠프 드 라 리그 바스켈전(70분 출전, 승부차기 승)",
        "시즌은 8월 1일 기준이며 리옹은 7월 10일 기준(7월 트로페 데 샹피옹이 새 시즌), 델리 다이너모스(인도 슈퍼리그, 10~12월 시즌)는 달력 연도 기준. 클럽 경계는 Transfermarkt 이적일(2000.7.28 갱강, 2003.7.22 리옹, 2007.7.9 첼시, 2013.7.18 트라브존스포르, 2014.9.17 메스, 2015.8.23 델리, 2016.1.29~7.19 와디 데글라 임대, 2018.1.25 디페르당주)",
        "우승·수상은 Transfermarkt 업적 페이지 기준: 챔피언스리그 11/12(첼시), 리그 우승 프랑스 03/04~06/07(리옹)·잉글랜드 09/10(첼시), FA컵 2009·2010·2012, 프랑스 슈퍼컵(트로페 데 샹피옹)·커뮤니티 실드 09/10, 프랑스 2부 우승 96/97(샤토루), 개인은 06/07 리그1 올해의 선수",
        "2018.5.4 위스테르트전(후반 교체, 도움은 뺌)이 마지막 경기였고 Transfermarkt는 2018.7.1 은퇴로 기록함",
    ]
    NOTE = "\n".join(L)
    for bad in ["dc", "dk", "dsf", "ko", "OTHER_LEG", "seasonOf", "v1.", "SELFA", "GAP", "KEEP_"]:
        if re.search(r"(?<![A-Za-z])" + re.escape(bad) + r"(?![A-Za-z])", NOTE): sys.exit("설명에 작업용 표현: " + bad)
    return NOTE
